def step_resp(h, N=5):
    return np.cumsum(h[:N])

options = {
 'A': (1,2), 'B': (0,1), 'C': (-1,0), 'D': (0,-1),
 'E': (-1,-1), 'F': (-1,2), 'G': (-2,1), 'H': (2,1)
}

