    h2 = np.array([2.0, b, 0,0,0])
    h3 = np.convolve(h1,h2)
    h4 = h1+h2
    r3 = step_resp(h3)
    r4 = step_resp(h4)
    print(k, "a=",a,"b=",b, "r3[:3]=",r3[:3], "r4[:3]=",r4[:3])

